// Pos is the object's position as a Pos (usable by pos-taking actions).
func (o Nuke) Pos() Pos {
	ref := RoomRef(0)
	if r := int(o.Rm()); r >= 0 && r < o.c.NRoom() {
		ref = RoomRef(o.c.RoomRef(r))
	}
	return MakePos(int(o.X()), int(o.Y()), ref)
}

// Flag is a row of the flag table. It is only valid during the tick it was obtained.
type Flag struct {
	c *Ctx
	i int
}

// H is the object's handle, the argument actions and queries take.
func (o Flag) H() Handle { return o.c.FlagH(o.i) }

// Handle lets the wrapper be passed wherever an Object is expected.
func (o Flag) Handle() Handle { return o.H() }

// Index is the row index in the flag table.
func (o Flag) Index() int { return o.i }

// Flags returns every packed flag row.
func (c *Ctx) Flags() []Flag {
	r := make([]Flag, c.NFlag())
	for i := range r {
		r[i] = Flag{c, i}
	}
	return r
}

